content.content:
# Component catalog

One line per component. Each guide lists props, variants, tokens, accessibility and examples. For the rules behind them, see [design-system.md](design-system.md).

| Component | Purpose | Guide |
|---|---|---|
| Badge | A small inline label that marks a card or states a short fact in a pill. | [src/components/Badge/Badge.md](../src/components/Badge/Badge.md) |
| Button | The single button component: a call to action that navigates or triggers an action. | [src/components/Button/Button.md](../src/components/Button/Button.md) |
| CurrencyTable | A two-column data table with an optional trend icon, a title and an update chip. | [src/components/CurrencyTable/CurrencyTable.md](../src/components/CurrencyTable/CurrencyTable.md) |
| FeatureCard | A compact card for a product feature: icon, title and a short description. | [src/components/FeatureCard/FeatureCard.md](../src/components/FeatureCard/FeatureCard.md) |
| Icon | An inline SVG icon that takes its colour from the surrounding text colour. | [src/components/Icon/Icon.md](../src/components/Icon/Icon.md) |
| PlanCard | A pricing card for one plan with a price, a note, an optional badge and a call to action. | [src/components/PlanCard/PlanCard.md](../src/components/PlanCard/PlanCard.md) |
| SectionTitle | A heading with an optional lead paragraph, coloured for the surface it sits on. | [src/components/SectionTitle/SectionTitle.md](../src/components/SectionTitle/SectionTitle.md) |
src/components:
Badge
Button
CurrencyTable
FeatureCard
Icon
PlanCard
SectionTitle

src/data:
currencies.json
features.json
index.ts
plans.json

src/pages:
index.astro
---
import BaseLayout from "../layouts/BaseLayout.astro";
import Button from "../components/Button/Button.astro";
import SectionTitle from "../components/SectionTitle/SectionTitle.astro";
import FeatureCard from "../components/FeatureCard/FeatureCard.astro";
import PlanCard from "../components/PlanCard/PlanCard.astro";
import CurrencyTable from "../components/CurrencyTable/CurrencyTable.astro";
import { currencies, features, plans } from "../data";
---

<BaseLayout>
    <header>
      <img src="/assets/img/logo.svg" alt="Batatabit" />
      <div class="header--title-container">
        <SectionTitle
          level={1}
          tone="on-gradient"
          title="La próxima revolución en el intercambio de criptomonedas."
          lead="Batatabit te ayuda a navegar entre los diferentes precios y tendencias."
        />
        <div class="hero-cta">
          <Button variant="light" as="a" href="#plans" icon="arrow-down">Conoce Nuestros Planes</Button>
        </div>
      </div>
    </header>
    <main>
      <section class="main-exchange-container">
        <div class="backgroundImg"></div>
        <div class="main-exchange-container--title">
          <SectionTitle
            level={2}
            tone="on-light"
            title="Visibilizamos todas las tasas de cambio."
            lead="Traemos información en tiempo real de las casas de cambio y las monedas más importantes del mundo."
          />
        </div>
        <section class="main-tables-container">
          {currencies.map((table) => <CurrencyTable {...table} />)}
        </section>
      </section>
      <section class="main-product-detail">
        <div class="product-detail--title">
          <SectionTitle
            level={2}
            tone="on-dark"
            title="Creamos un producto sin comparación."
            lead="Confiable y diseñado para su uso diario."
          />
        </div>
        <section class="product-cards--container">
          {features.map((feature) => <FeatureCard {...feature} />)}
        </section>
      </section>
      <section class="bitcoin-img-container">
        <SectionTitle level={2} tone="on-dark" title="Conócelo hoy." />
      </section>
      <section id="plans" class="main-plans-container">
        <div class="plans--title">
          <SectionTitle
            level={2}
            tone="on-light"
            title="Escoge el plan que mejor se ajuste a ti."
            lead="Cualquier plan te da acceso completo a nuestra plataforma."
          />
        </div>
        <section class="plans-container--slider">
          {plans.map((plan) => <PlanCard {...plan} />)}
        </section>
      </section>
    </main>
    <footer>
      <section class="left">
        <ul>
          <li><a href="#">Linkedin</a></li>
          <li><a href="#">Crunchbase</a></li>
          <li><a href="#">Hackernews</a></li>
        </ul>
      </section>
      <section class="right">
        <img src="/assets/img/logo-footer.svg" alt="Batatabit" />
      </section>
    </footer>
</BaseLayout>
---
import Icon from "../Icon/Icon.astro";

interface BaseProps {
  /**
   * Visual style. `light` = filled button with shadow (hero call to action, 229px wide);
   * `outline` = button with an accent border for secondary actions (plan cards, 150px wide).
   */
  variant: "light" | "outline";
  /** Optional trailing icon. Decorative; the label must carry the meaning. */
  icon?: "arrow-down" | "arrow-right";
  /**
   * Accessible name override. Use it when the visible label is ambiguous out of context
   * (e.g. several "Escoger este" buttons); keep the visible label inside it (WCAG 2.5.3).
   * @default undefined (the visible label is the name)
   */
  ariaLabel?: string;
}

export interface LinkProps extends BaseProps {
  /** Render an `<a>` (navigation). Requires `href`. */
  as: "a";
  /** Link target (e.g. `#plans`). Required when `as="a"`. */
  href: string;
}

export interface ActionProps extends BaseProps {
  /**
   * Render a `<button type="button">` (in-page action).
   * @default "button"
   */
  as?: "button";
  href?: never;
}

export type Props = LinkProps | ActionProps;

const props = Astro.props;
const { variant, icon, ariaLabel } = props;
const classes = ["button", `button--${variant}`];
---

{
  props.as === "a" ? (
    <a class:list={classes} href={props.href} aria-label={ariaLabel}>
      <slot />
      {icon && (
        <span class="button__icon">
          <Icon name={icon} />
        </span>
      )}
    </a>
  ) : (
    <button class:list={classes} type="button" aria-label={ariaLabel}>
      <slot />
      {icon && (
        <span class="button__icon">
          <Icon name={icon} />
        </span>
      )}
    </button>
  )
}

<style>
  .button {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-8);
    height: 48px;
    padding: 0 var(--space-16);
    background-color: var(--color-surface-button);
    border-radius: var(--radius-button);
    color: var(--color-on-button);
    font-family: var(--text-button-family);
    font-size: var(--text-button-size);
    font-weight: var(--text-button-weight);
    line-height: var(--text-button-line);
  }

  .button--light {
    width: 229px;
    box-shadow: var(--shadow-on-light);
    text-decoration: none;
  }

  .button--outline {
    display: inline-flex;
    min-width: 150px;
    white-space: nowrap;
    border: var(--border-button) solid var(--color-border-accent);
    cursor: pointer;
  }

  .button__icon {
    display: inline-block;
  }

  .button--light .button__icon {
    width: 13px;
    height: 8px;
    color: var(--color-on-button);
  }

  .button--outline .button__icon {
    width: 20px;
    height: 20px;
    color: var(--color-primary);
  }
</style>
/*
  1. Posicionamimento
  2. Modelo de caja (Box model) [margin, padding, tamaño]
  3. Tipografia
  4. Visuales [Shadow box, Border Radius]
  5. Otros
*/

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  padding: 0;
}

html {
  font-size: 62.5%;
  font-family: var(--font-body);
}

/* Anillo de foco del teclado para todo elemento enfocable (enlaces, botones, [tabindex]). */
:focus-visible {
  outline: var(--focus-ring-width) solid var(--color-focus-ring);
  outline-offset: var(--focus-ring-offset);
}

header {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  min-width: 320px;
  min-height: var(--layout-hero-min-height);
  padding-top: var(--layout-hero-padding-top);
  text-align: center;
  background: var(--gradient-hero);
}

header img {
  width: var(--layout-hero-logo-width);
  height: auto;
  margin-top: var(--layout-hero-logo-margin-top);
  align-self: center;
}

.header--title-container {
  width: 90%;
  min-width: 288px;
  max-width: 900px;
  margin-top: var(--space-40);
  text-align: center;
  align-self: center;
}

/* El CTA queda centrado sobre el borde inferior del hero. */
.hero-cta {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  justify-content: center;
  transform: translateY(50%);
}

main {
  width: 100%;
  height: auto;
  background-color: var(--color-surface-page);
}

.main-exchange-container {
  width: 100%;
  height: auto;
  padding-top: var(--space-80);
  padding-bottom: var(--space-32);
  text-align: center;
}

.main-exchange-container--title {
  width: 90%;
  min-width: 288px;
  max-width: 900px;
  margin: 0 auto var(--space-32);
}

.main-exchange-container .backgroundImg {
  width: 200px;
  height: 200px;
  margin: 0 auto;
  margin-bottom: var(--space-48);
  background-image: url("/assets/img/Bitcoin.svg");
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.main-product-detail {
  position: relative;
  width: 100%;
  min-width: 320px;
  height: auto;
  padding: var(--space-20) var(--space-12);
  background-color: var(--color-surface-dark);
}

.product-detail--title {
  width: 90%;
  min-width: 288px;
  height: auto;
  margin: 0 auto;
  margin-top: var(--space-48);
  margin-bottom: var(--space-20);
  text-align: center;
}

.bitcoin-img-container {
  width: 100%;
  min-width: 320px;
  height: 50vh;
  background-image: var(--gradient-image-scrim), url("/assets/img/bitcoinbaby2x.jpg");
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
  padding-top: var(--space-64);
}

.main-plans-container {
  width: 100%;
  min-width: 320px;
  padding-bottom: var(--space-64);
  text-align: center;
}

.plans--title {
  width: 90%;
  min-width: 288px;
  height: auto;
  margin: 0 auto;
  margin-bottom: var(--space-48);
  padding-top: var(--space-48);
}

.plans-container--slider {
  display: flex;
  /* gap: 50px; */
  height: 316px;
  overflow-x: scroll;
  overscroll-behavior-x: contain;
  scroll-snap-type: x proximity;
}

footer {
  display: flex;
  width: 100%;
  min-height: var(--layout-footer-min-height);
  background-color: var(--color-primary);
}

footer section {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 50%;
}

footer .left ul {
  font-size: var(--text-lead-size);
  font-weight: var(--text-lead-weight);
  line-height: var(--text-lead-line);
  list-style: none;
}

.left li {
  margin: var(--space-12) 0;
}

.left a {
  text-decoration: none;
  color: var(--color-on-primary);
}

/* 768px = breakpoint.tablet (las custom properties no se pueden usar en @media). */
@media (min-width: 768px) {
  /* Dos tablas centradas, una junto a la otra (Figma: 22px entre ellas; 24px es el escalón más cercano). */
  .main-tables-container {
    display: flex;
    align-items: flex-start;
    justify-content: center;
    gap: var(--space-24);
    width: 100%;
    max-width: var(--layout-content-max-width);

