---
import BaseLayout from "../layouts/BaseLayout.astro";
import Button from "../components/Button/Button.astro";
import SectionTitle from "../components/SectionTitle/SectionTitle.astro";
import TextField from "../components/TextField/TextField.astro";
---

<BaseLayout title="Ingresar | Batatabit">
  <main class="login">
    <a class="login__logo" href="/">
      <img src="/assets/img/logo.svg" alt="Batatabit, ir al inicio" />
    </a>
    <div class="login__card">
      <SectionTitle
        level={1}
        tone="on-light"
        title="Ingresa a tu cuenta."
        lead="Accede a los precios y tendencias en tiempo real."
      />
      <form class="login__form" method="post">
        <TextField
          label="Correo electrónico"
          name="email"
          type="email"
          autocomplete="email"
          required
        />
        <TextField
          label="Contraseña"
          name="password"
          type="password"
          autocomplete="current-password"
          required
        />
        <a class="login__forgot" href="#">¿Olvidaste tu contraseña?</a>
        <div class="login__action">
          <Button variant="outline" as="button" type="submit" icon="arrow-right">Ingresar</Button>
        </div>
      </form>
    </div>
  </main>
</BaseLayout>

<style>
  .login {
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 320px;
    min-height: 100vh;
    padding: var(--layout-hero-padding-top) var(--space-16) var(--space-48);
    background: var(--gradient-hero);
  }

  .login__logo {
    margin-top: var(--layout-hero-logo-margin-top);
  }

  .login__logo img {
    display: block;
    width: var(--layout-hero-logo-width);
    height: auto;
  }

  .login__card {
    width: 100%;
    max-width: 420px;
    margin-top: var(--space-40);
    padding: var(--space-32) var(--space-20);
    background-color: var(--color-surface-card);
    border-radius: var(--radius-card);
    box-shadow: var(--shadow-on-dark);
  }

  .login__form {
    display: flex;
    flex-direction: column;
    gap: var(--space-20);
    margin-top: var(--space-32);
  }

  .login__forgot {
    align-self: flex-start;
    padding-block: var(--space-4);
    font-family: var(--text-body-sm-family);
    font-size: var(--text-body-sm-size);
    font-weight: var(--text-body-sm-weight);
    line-height: var(--text-body-sm-line);
    color: var(--color-text-strong);
    text-decoration: underline;
  }

  .login__action {
    display: flex;
    justify-content: center;
  }

  /* 768px = breakpoint.tablet. */
  @media (min-width: 768px) {
    .login {
      padding-top: var(--layout-hero-padding-top-tablet);
    }

    .login__logo {
      margin-top: var(--layout-hero-logo-margin-top-tablet);
    }

    .login__logo img {
      width: var(--layout-hero-logo-width-tablet);
    }

    .login__card {
      padding: var(--space-48);
    }
  }
</style>
E
